style.css:
@-moz-document domain("roblox.com") {
/* Aplica a imagem no fundo absoluto do site */
  html, body, .rbx-body, #wrap, .content, .main-layout, .content-wrapper {
    background-image: url('https://ibb.co') !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center top !important;
    background-repeat: no-repeat !important;
  }

  /* Força TODAS as caixas escuras do Roblox a ficarem transparentes */
  .dark-theme, .theme-dark, .section, .section-content, .container-main, .container-header, .game-card, .item-card, #container-main, .grid-item-container, .dark-theme .section-content, .rbx-tab-content {
    background-color: rgba(21, 22, 26, 0.55) !important;
    background: rgba(21, 22, 26, 0.55) !important;
    border: none !important;
  }

  /* Deixa o fundo do feed de amigos e jogos transparente */
  .game-home-page-container, .places-list, .wide-game-tile {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Cabeçalho superior (Azul do traje) */
  .navbar-default, .rbx-header, .notification-stream-base, #header {
    background-color: #1e6bbb !important;
  }

  /* Menu lateral esquerdo */
  .left-navigation, .menu-sidebar, #navigation, .navigation-container {
    background-color: rgba(15, 16, 20, 0.85) !important;
  }

  /* Botões personalizados */
  .btn-secondary-md, .btn-primary-md, .btn-to-all {
    background-color: #15161a !important;
    color: #1e6bbb !important;
    border: 1px solid #1e6bbb !important;
  }
  
  /* Letras brancas */
  h1, h2, h3, h4, h5, h6, span, p, a, .text, .text-name, .game-card-name, .text-title {
    color: #ffffff !important;
  }
}
